<?php
declare(strict_types=1);
namespace App\Actions;
use App\Models\{EventCompetition,EventCompetitionScore,User}; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class CorrectEventCompetitionScore { public function handle(User $actor, EventCompetitionScore $score,int $units,string $reason,string $key):EventCompetitionScore{return DB::transaction(function()use($actor,$score,$units,$reason,$key){$s=EventCompetitionScore::query()->with('revisions')->lockForUpdate()->findOrFail($score->id);$assignment=\App\Models\EventCompetitionJudgeAssignment::query()->lockForUpdate()->findOrFail($s->judge_assignment_id);$competition=EventCompetition::query()->lockForUpdate()->findOrFail($assignment->competition_id);if(in_array($competition->status->value,['finalized','published'],true)||$assignment->judge_user_id!==$actor->id||blank($reason)){throw new AuthorizationException;}$next=$s->current_revision_number+1;$s->revisions()->create(['revision_number'=>$next,'value_units'=>$units,'actor_user_id'=>$actor->id,'reason_code'=>$reason,'idempotency_key'=>$key,'created_at'=>now()]);$s->update(['current_revision_number'=>$next]);return $s;},3);} }
